/**
 * Every RS3 Area Tasks achievement (also called the Achievement Diaries) —
 * one entry per region, each holding its tier list (Beginner/Easy/Medium/
 * Hard/Elite, whichever the region actually has — Lumbridge alone has a
 * Beginner tier and no Elite one) and, per tier, the individual tasks
 * (name, description, notes, wiki link, per-task requirements) plus that
 * tier's own unlock requirements and reward-NPC/lamp details.
 *
 * Scraped from the wiki's own per-region pages
 * (https://runescape.wiki/w/Area_Tasks_achievements and each region's own
 * "<Region> achievements" page, e.g.
 * https://runescape.wiki/w/Morytania_achievements) rather than hand-
 * transcribed — there's no single page with everything on it: a region's
 * own overview page (taskmasters, lamp totals, the region's final reward
 * item, combined max skill levels) transcludes its four
 * "<Tier> <Region> achievements" subpages, and it's those subpages that
 * carry both the actual task list (name/description/requirements/notes/
 * RuneScore, one wiki table per tier) AND the one thing that isn't on the
 * overview page at all — the *per-tier* unlock requirements (skills/quests
 * needed to even attempt that tier's tasks, plus a short recommended-items
 * list). `rewardProgression` is the region's reward-item chain (e.g.
 * Morytania legs 1-4) with what each stage's bonuses are when worn/
 * operated/always-active — every tier subpage renders the *same* full
 * chain table (later stages just start hidden in-game until unlocked), so
 * it's only captured once per region rather than once per tier.
 *
 * `requirements` (both a tier's own and each task's own) is an array of
 * `{ text, quest }` — `text` free-form ("25 Crafting", "Priest in Peril",
 * "70 Ranged or"), `quest` true only when the wiki itself marked that
 * particular requirement as a quest rather than a skill one (its own
 * `achievement-req-quest` HTML class for a task's requirement, a bare
 * `[[Quest Name]]` wikilink for a tier's). `text` still isn't further
 * split into a structured skill-or-quest shape beyond that one flag — same
 * "human-readable text over a bespoke schema" call as agility-courses.js/
 * fishing-methods.js — TasksTab.vue's own parseRequirement
 * (web/src/lib/areaTasks.ts) is what pulls a skill + level back out of
 * `text` at render time via a plain regex, `quest` only needed for the
 * one case that regex can't (a quest name has no reliable pattern of its
 * own to match against). `notes` is `null` wherever the wiki table's own
 * Notes cell was just a restatement of the Description cell (common for
 * simple one-line tasks) rather than genuinely extra detail.
 *
 * Not hand-maintained — re-scrape a region's pages by hand if Jagex ships
 * a new task or reworks an existing one; nothing here is edited day to
 * day.
 */

