            description: 'Be on the winning side in a game of Castle Wars.',
            members: true,
            requirements: [],
            notes: 'Be on the winning side in a game of Castle Wars. A draw will not count. This achievement does not require everyone in the match to be present at the end. It can be completed by having four players join a match, having the player who needs the achievement score, and then the other three players can simply leave via the exit portals. The player wanting the achievement MUST stay until the end of the match, however. It is possible to complete this achievement with only one other player by doing the following steps: Go to the Castle Wars lobby with the other player. One player must enter the Zamorak portal and the other player must enter the Saradomin portal. Both players logout/go to lobby and re-enter the same world that you were in previously. Enter the same portals again. A 3 minute countdown should appear if successful. Afterwards, get 1 point and wait till you win. The other player can leave by waiting a few minutes where they spawned. It is also possible to exit a match halfway through if your team is losing (and you know that the other team is going to win.) Then enter the winning teams portal to re-join the match on the winning side and get the achievement. Please note however that you can only re-join if someone else leaves the match from the team you are trying to join, so there is a chance that if you leave you might not be able to re-join.',
